ACTIONS = {
    "checkout": {"version": "v4", "run": lambda inputs: {"path": inputs.get("path", ".")}},
    "deploy-cloud": {"version": "v2", "run": lambda inputs: {"url": f"https://{inputs['region']}.example.com/app"}},
}

def use_action(name, version, inputs):
    action = ACTIONS[name]
    if action["version"] != version:
        return {"error": f"version {version} no coincide con {action['version']}"}
    return action["run"](inputs)

step1 = use_action("checkout", "v4", {"path": "src"})
print("checkout ->", step1)
step2 = use_action("deploy-cloud", "v2", {"region": "eu-west-1"})
print("deploy-cloud ->", step2)
print("URL final:", step2["url"])
